CREATE TABLE IF NOT EXISTS membership_coupons(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('percent','fixed')),percent_bps INTEGER NOT NULL DEFAULT 0,fixed_units TEXT NOT NULL DEFAULT '0',plan_ids TEXT NOT NULL DEFAULT '[]',starts_at INTEGER NOT NULL,expires_at INTEGER,max_uses INTEGER NOT NULL DEFAULT 0 CHECK(max_uses>=0),per_account_limit INTEGER NOT NULL DEFAULT 1 CHECK(per_account_limit>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),created_by TEXT NOT NULL,created_at INTEGER NOT NULL);
ALTER TABLE membership_purchases ADD COLUMN coupon_id TEXT REFERENCES membership_coupons(id);
ALTER TABLE membership_purchases ADD COLUMN coupon_code TEXT NOT NULL DEFAULT '';
ALTER TABLE membership_purchases ADD COLUMN discount_units TEXT NOT NULL DEFAULT '0';
CREATE TABLE IF NOT EXISTS membership_coupon_uses(order_id TEXT PRIMARY KEY REFERENCES membership_purchases(id),coupon_id TEXT NOT NULL REFERENCES membership_coupons(id),account_id TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,redeemed_at INTEGER,released_at INTEGER);
CREATE INDEX IF NOT EXISTS membership_coupon_quota ON membership_coupon_uses(coupon_id,account_id,redeemed_at,released_at,expires_at);
CREATE TABLE IF NOT EXISTS membership_coupon_audit(id TEXT PRIMARY KEY,coupon_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER membership_coupon_reserve BEFORE INSERT ON membership_coupon_uses WHEN NOT EXISTS(
 SELECT 1 FROM membership_coupons c JOIN membership_purchases p ON p.id=NEW.order_id
 WHERE c.id=NEW.coupon_id AND p.coupon_id=c.id AND p.account_id=NEW.account_id AND p.settled_at IS NULL AND p.cancelled_at IS NULL AND NEW.redeemed_at IS NULL AND NEW.released_at IS NULL
 AND c.active=1 AND c.starts_at<=NEW.created_at AND (c.expires_at IS NULL OR c.expires_at>NEW.created_at) AND NEW.expires_at=p.expires_at AND NEW.expires_at>NEW.created_at AND (c.expires_at IS NULL OR NEW.expires_at<=c.expires_at)
 AND (json_array_length(c.plan_ids)=0 OR EXISTS(SELECT 1 FROM json_each(c.plan_ids) WHERE value=p.plan))
 AND (c.max_uses=0 OR (SELECT COUNT(*) FROM membership_coupon_uses u WHERE u.coupon_id=c.id AND (u.redeemed_at IS NOT NULL OR (u.released_at IS NULL AND u.expires_at>NEW.created_at)))<c.max_uses)
 AND (c.per_account_limit=0 OR (SELECT COUNT(*) FROM membership_coupon_uses u WHERE u.coupon_id=c.id AND u.account_id=NEW.account_id AND (u.redeemed_at IS NOT NULL OR (u.released_at IS NULL AND u.expires_at>NEW.created_at)))<c.per_account_limit)
) BEGIN SELECT RAISE(ABORT,'coupon_unavailable'); END;
CREATE TRIGGER membership_coupon_release AFTER UPDATE OF cancelled_at ON membership_purchases WHEN OLD.cancelled_at IS NULL AND NEW.cancelled_at IS NOT NULL AND NEW.coupon_id IS NOT NULL BEGIN UPDATE membership_coupon_uses SET released_at=NEW.cancelled_at WHERE order_id=NEW.id AND redeemed_at IS NULL; END;
CREATE TRIGGER membership_coupon_redeem AFTER UPDATE OF settled_at ON membership_purchases WHEN OLD.settled_at IS NULL AND NEW.settled_at IS NOT NULL AND NEW.coupon_id IS NOT NULL BEGIN UPDATE membership_coupon_uses SET redeemed_at=NEW.settled_at WHERE order_id=NEW.id AND redeemed_at IS NULL AND released_at IS NULL; END;
DROP TRIGGER IF EXISTS membership_duration_purchase;
DROP TRIGGER IF EXISTS membership_duration_settlement;
DROP TRIGGER IF EXISTS membership_locked_quote;
CREATE TRIGGER membership_duration_purchase BEFORE INSERT ON membership_purchases WHEN NOT (NEW.credit_units='0' AND NEW.kind IN ('purchase','renewal') AND CAST(NEW.discount_units AS INTEGER)>=0 AND CAST(NEW.discount_units AS INTEGER)<=CAST(NEW.list_units AS INTEGER) AND CAST(NEW.amount AS INTEGER)=CAST(NEW.list_units AS INTEGER)-CAST(NEW.discount_units AS INTEGER) AND (
(NEW.plan='month' AND NEW.months=1 AND NEW.list_units='1000000') OR (NEW.plan='quarter' AND NEW.months=3 AND NEW.list_units='2000000') OR (NEW.plan='half-year' AND NEW.months=6 AND NEW.list_units='3000000') OR (NEW.plan='year' AND NEW.months=12 AND NEW.list_units='5000000')) AND (
(NEW.coupon_id IS NULL AND NEW.discount_units='0' AND NEW.coupon_code='') OR EXISTS(SELECT 1 FROM membership_coupons c WHERE c.id=NEW.coupon_id AND c.code=NEW.coupon_code AND CAST(NEW.discount_units AS INTEGER)=MIN(CAST(NEW.list_units AS INTEGER),CASE WHEN c.kind='percent' THEN CAST(NEW.list_units AS INTEGER)*c.percent_bps/10000 ELSE CAST(c.fixed_units AS INTEGER) END)))) BEGIN SELECT RAISE(ABORT,'coupon_terms_invalid'); END;
CREATE TRIGGER membership_duration_settlement BEFORE UPDATE OF settled_at ON membership_purchases WHEN OLD.settled_at IS NULL AND NEW.settled_at IS NOT NULL AND NOT (NEW.credit_units='0' AND NEW.kind IN ('purchase','renewal') AND CAST(NEW.discount_units AS INTEGER)>=0 AND CAST(NEW.discount_units AS INTEGER)<=CAST(NEW.list_units AS INTEGER) AND CAST(NEW.amount AS INTEGER)=CAST(NEW.list_units AS INTEGER)-CAST(NEW.discount_units AS INTEGER) AND (
(NEW.plan='month' AND NEW.months=1 AND NEW.list_units='1000000') OR (NEW.plan='quarter' AND NEW.months=3 AND NEW.list_units='2000000') OR (NEW.plan='half-year' AND NEW.months=6 AND NEW.list_units='3000000') OR (NEW.plan='year' AND NEW.months=12 AND NEW.list_units='5000000')) AND (
(NEW.coupon_id IS NULL AND NEW.discount_units='0' AND NEW.coupon_code='') OR EXISTS(SELECT 1 FROM membership_coupons c WHERE c.id=NEW.coupon_id AND c.code=NEW.coupon_code AND CAST(NEW.discount_units AS INTEGER)=MIN(CAST(NEW.list_units AS INTEGER),CASE WHEN c.kind='percent' THEN CAST(NEW.list_units AS INTEGER)*c.percent_bps/10000 ELSE CAST(c.fixed_units AS INTEGER) END))) AND (NEW.coupon_id IS NULL OR EXISTS(SELECT 1 FROM membership_coupon_uses u WHERE u.order_id=NEW.id AND u.coupon_id=NEW.coupon_id AND u.account_id=NEW.account_id AND u.released_at IS NULL AND u.redeemed_at IS NULL AND u.expires_at>NEW.settled_at))) BEGIN SELECT RAISE(ABORT,'coupon_terms_invalid'); END;
CREATE TRIGGER membership_locked_quote BEFORE UPDATE OF plan,months,amount,kind,list_units,credit_units,state_version,coupon_id,coupon_code,discount_units ON membership_purchases WHEN NEW.plan<>OLD.plan OR NEW.months<>OLD.months OR NEW.amount<>OLD.amount OR NEW.kind<>OLD.kind OR NEW.list_units<>OLD.list_units OR NEW.credit_units<>OLD.credit_units OR NEW.state_version<>OLD.state_version OR NEW.coupon_id IS NOT OLD.coupon_id OR NEW.coupon_code<>OLD.coupon_code OR NEW.discount_units<>OLD.discount_units BEGIN SELECT RAISE(ABORT,'quote_is_locked'); END;
CREATE TRIGGER membership_coupon_terms_locked BEFORE UPDATE OF code,kind,percent_bps,fixed_units,plan_ids,starts_at,expires_at,max_uses,per_account_limit ON membership_coupons BEGIN SELECT RAISE(ABORT,'coupon_definition_locked'); END;
